#!/usr/bin/env bash
set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

TEMP_ENV_CREATED=0
if [[ ! -f .env ]]; then
	cat > .env <<'ENVEOF'
# Auto-generated by deploy/release-check.sh for CI/local checks
FP_APP_PORT=8082
FP_DB_DEV_PORT=3310
FP_DB_TEST_PORT=3311

FP_DB_DEV_NAME=finanzas_personales_dev
FP_DB_DEV_USER=finanzas_dev
FP_DB_DEV_PASSWORD=finanzas_dev_pass
FP_DB_DEV_ROOT_PASSWORD=finanzas_dev_root_pass

FP_DB_TEST_NAME=finanzas_personales_test
FP_DB_TEST_USER=finanzas_test
FP_DB_TEST_PASSWORD=finanzas_test_pass
FP_DB_TEST_ROOT_PASSWORD=finanzas_test_root_pass

APP_NAME=Finanzas Personales
APP_DB_HOST=db_dev
APP_DB_PORT=3306
APP_DB_NAME=finanzas_personales_dev
APP_DB_USER=finanzas_dev
APP_DB_PASSWORD=finanzas_dev_pass
APP_DB_SSL_MODE=preferred
APP_DB_SSL_CA=
APP_DB_SSL_CERT=
APP_DB_SSL_KEY=
APP_DB_SSL_VERIFY_SERVER_CERT=0
APP_DB_ALLOW_INSECURE_REMOTE=1
ENVEOF
	TEMP_ENV_CREATED=1
fi

cleanup() {
	if [[ "$TEMP_ENV_CREATED" -eq 1 && -f .env ]]; then
		rm -f .env
	fi
}
trap cleanup EXIT

echo "[0/6] Levantando servicios locales requeridos"
docker compose -f compose.yaml up -d --build app db_dev >/dev/null

echo "[1/6] Validando compose"
docker compose -f compose.yaml config >/dev/null

echo "[2/6] Empaquetado y verificación de artefacto"
./deploy/deploy.sh >/dev/null

echo "[3/6] Verificando salud PHP en contenedor app"
docker compose -f compose.yaml exec -T app php /var/www/html/deploy/check-php.php >/dev/null

echo "[4/6] Verificando health web"
docker compose -f compose.yaml exec -T app php /var/www/html/deploy/web-check.php http://127.0.0.1 >/dev/null

echo "[5/6] Smoke local de espacios en db_dev"
docker compose -f compose.yaml exec -T app php /var/www/html/scripts/smoke_local.php >/dev/null

echo "[6/6] Estado final"
echo "RELEASE_CHECK_OK=1"
